def move_refs_before_punctuation(text, refs):
    ref_str = "".join([f"【{r}】" for r in refs])

    # 匹配句尾标点
    m = re.match(r"(.*?)([。！？；;,.!?])?$", text.strip())

    if not m:
        return text + ref_str

    body, punct = m.groups()

    if punct:
        return body + ref_str + punct
    else:
        return body + ref_str
    
def extract_refs(text):
    """
    提取引用编号，例如【10】【9】
    """
    refs = re.findall(r'【(\d+)】', text)
    return refs


def remove_refs(text):
    """
    删除引用标记
    """
    return re.sub(r'【\d+】', '', text)


def dedup_refs(refs):
    """
    引用去重
    """
    seen = set()
    result = []
    for r in refs:
        if r not in seen:
            seen.add(r)
            result.append(r)
    return result

