def remove_word_count(text: str) -> str:
    """
    删除类似（全文共998字）的结尾统计，包括前面的空格或回车
    """
    # 匹配：可能有空格/回车 + （全文共数字字）
    text = re.sub(r'[\s\r\n]*（全文共?约?\s*\d+\s*字）', '', text)
    return text


def verify_references_with_llm(reference: str, statements: List[str]) -> List[Dict[str, str]]:
    """
    使用LLM验证引用的准确性
    
    Args:
        reference: 参考资料内容
        statements: 需要验证的语句列表
    
    Returns:
        List[Dict[str, str]]: 验证结果列表，每个元素包含idx和result
    """

    prompt_template="""
    你会看到一个参考资料和一个statement，请判断statement中的数字与参考资料中的数字是否有相同含义。  
    - 如果数字具有相同的含义（允许四舍五入），返回 `supported`。
    - 如果数字含义不同，返回 `unsupported`。
    - 如果无法判断，返回 `unknown`。

    例子1：
    <reference>
    截至2020年底，全国832个贫困县全部摘帽，剩余贫困人口如期脱贫，已实现“两不愁三保障”全面覆盖。
    </reference>
    <statement>
    截至去年底，剩余的832个贫困县已经脱贫摘帽。
    </statement>
    输出：supported

    例子2：
    <reference>
    扶贫开发领导小组成员单位先后出台了40多项政策文件，帮助解决疫情带来的困境。
    </reference>
    <statement>
    该基地直接带动300人稳定就业，其中脱贫户占比达40%。
    </statement>
    输出：unsupported

    下面是参考资料和statement：  
    <reference>  
    {reference}  
    </reference>  
    <statement>  
    {statement}  
    </statement>  
    请不要输出 supported 或者 unsupported 或者 unknown 以外的任何内容，只能输出一个词
    开始判断：
    """
    # 只处理第一个statement
    if not statements:
        return [{"idx": 1, "result": "unknown"}]
    
    statement = statements[0]
    
    # 填充prompt
    prompt = prompt_template.format(
        reference=reference,
        statement=statement
    )
    logger.info(f"prompt:{prompt}")
    # 获取LLM
    llm = get_llm_by_type(AGENT_LLM_MAP.get("reporter", "default"))
    #llm = get_llm_by_type(AGENT_LLM_MAP.get("support_verifier", "default"))
    
    # 调用LLM
    try:
        response = llm.invoke(prompt, config={"tags": ["noshow"]})
        content = response.content.strip()
        logger.info(f"LLM返回结果: {content}")
        # 验证结果是否合法
        if content in ["supported", "unsupported", "unknown"]:
            return [{"idx": 1, "result": content}]
        else:
            # 结果不合法，返回unknown
            logger.error(f"LLM返回了非法结果: {content}")
            return [{"idx": 1, "result": "unknown"}]
    except Exception as e:
        logger.error(f"LLM验证引用失败: {str(e)}")
        # 失败时返回默认结果
        return [{"idx": 1, "result": "unknown"}]



import asyncio

async def verify_with_executor(reference: str, prompt: str, llm):
    loop = asyncio.get_event_loop()
    return await loop.run_in_executor(None, llm.invoke, prompt, {"tags": ["noshow"]})
async def verify_references_with_llm_async(reference: str, statements: List[str]) -> List[Dict[str, str]]:

    prompt_template="""
    你会看到一个参考资料和一个statement，请判断statement中的数字与参考资料中的数字是否有相同含义。  
    - 如果数字具有相同的含义（允许四舍五入），返回 `supported`。
    - 如果数字含义不同，返回 `unsupported`。
    - 如果无法判断，返回 `unknown`。

    例子1：
    <reference>
    截至2020年底，全国832个贫困县全部摘帽，剩余贫困人口如期脱贫，已实现“两不愁三保障”全面覆盖。
    </reference>
    <statement>
    截至去年底，剩余的832个贫困县已经脱贫摘帽。
    </statement>
    输出：supported

    例子2：
    <reference>
    扶贫开发领导小组成员单位先后出台了40多项政策文件，帮助解决疫情带来的困境。
    </reference>
    <statement>
    该基地直接带动300人稳定就业，其中脱贫户占比达40%。
    </statement>
    输出：unsupported

    下面是参考资料和statement：  
    <reference>  
    {reference}  
    </reference>  
    <statement>  
    {statement}  
    </statement>  
    请不要输出 supported 或者 unsupported 或者 unknown 以外的任何内容，只能输出一个词
    开始判断：
    """
    llm = get_llm_by_type(AGENT_LLM_MAP.get("reporter", "default"))
    tasks = []

    # 将多个statement批量发送
    for statement in statements:
        prompt = prompt_template.format(reference=reference, statement=statement)

        # 使用 verify_with_executor 来异步执行 llm.invoke
        tasks.append(verify_with_executor(reference, prompt, llm))

    # 异步调用并等待结果
    responses = await asyncio.gather(*tasks)

    results = []
    for response in responses:
        response = response.content.strip()
        if response in ["supported", "unsupported", "unknown"]:
            results.append({"idx": 1, "result": response})
        else:
            results.append({"idx": 1, "result": "unknown"})
    return results



async def verify_citation_semantic_async(
    reference: str, statement: str
) -> bool | None:
    """
    语义层面验证：判断 reference 是否能支撑 statement 的核心内容。
    返回 True=支撑, False=不支撑, None=不确定(调用方倾向保留)。
    """
    prompt = f"""你会看到一段参考资料和一段陈述，请判断陈述的核心内容是否能在参考资料中找到依据或支撑。

判断标准：
- 参考资料直接或间接支撑了陈述的核心内容，且关键数字、事实一致 → 返回 supported
- 参考资料与陈述内容不相关、相矛盾，或关键数字不一致 → 返回 unsupported
- 无法判断 → 返回 unknown

注意：
- 允许陈述对参考资料内容进行概括、改写或引申，语义相符即可
- 陈述中的关键数字（户数、人数、金额、比例等）必须在参考资料中有对应依据，否则返回 unsupported
- 若陈述说「586户」而参考资料说「1273户」，属于矛盾，返回 unsupported
- 若陈述说「2000万」「50万」而参考资料完全未提及这些数字，返回 unsupported

例1：
<reference>
"双11"期间订单量很大，我们要确保供应充足、配送及时。
</reference>
<statement>
借鉴广东农产品电商"双11"期间订单量激增的经验，建成深加工产业链。
</statement>
输出：supported

例2：
<reference>
市政府建立医疗集团法人治理结构，城区18个社区卫生服务机构由两大医疗集团统一管理。
</reference>
<statement>
"智慧湘北"平台整合18个部门数据，实现对5000余户重点人群动态预警。
</statement>
输出：unsupported

<reference>
{reference}
</reference>
<statement>
{statement}
</statement>
只输出 supported、unsupported 或 unknown 中的一个词："""

    llm = get_llm_by_type(AGENT_LLM_MAP.get("reporter", "default"))
    try:
        loop = asyncio.get_event_loop()
        response = await loop.run_in_executor(
            None, llm.invoke, prompt, {"tags": ["noshow"]}
        )
        result = response.content.strip().lower()
        logger.info(f"语义验证结果: {result}")
        if result == "supported":
            return True
        elif result == "unsupported":
            return False
        else:
            return None  # unknown → 调用方视为"保留"
    except Exception as e:
        logger.error(f"语义LLM验证失败: {e}")
        return None


