CHINESE_NUMBERS = {
    "零":0,"一":1,"二":2,"三":3,"四":4,"五":5,
    "六":6,"七":7,"八":8,"九":9,
    "十":10,"百":100,"千":1000,"万":10000,"亿":100000000
}

ARABIC_UNIT_MULTIPLIER = {
    "十":10,"百":100,"千":1000,"万":10000,"亿":100000000
}


def is_boundary(ch: str):
    return ch in "。！？；;!?\n\r"


from typing import List

def _normalize_for_filter(text: str) -> str:
    """用于短句过滤的简易归一化：去标点、空格，与前端 normalizeForNgram 语义一致"""
    t = re.sub(r"【\d+】", "", text or "")
    t = t.lower().strip()
    t = re.sub(r"\s+", "", t)
    t = re.sub(r"[，,。.!！？?；;：:\u201c\u201d\u2018\u2019\"\"''\（\）()\[\]【】<>《》、/\\|@#$%^&*_+=\-~`]", "", t)
    return t


# 与前端 report/citationMatch.ts isBoundary 对齐的切分符
_SPLIT_BOUNDARY_CHARS = set("。！？!?；;")
_QUOTE_CHARS = {'"', '"', '"', "'", "'", "'"}


def _split_line_quote_aware(line: str) -> List[str]:
    """
    按句末标点、换行切分，但引号内的。！？不参与切分。
    避免 "每天都有工钱，一个月能挣2800多元呢。" 被误切成多段。
    """
    parts: List[str] = []
    buf: List[str] = []
    in_quote = False

    i = 0
    while i < len(line):
        ch = line[i]
        # 换行始终切分
        if ch == "\n" or ch == "\r":
            if buf:
                s = "".join(buf).strip()
                if s:
                    parts.append(s)
                buf = []
            if ch == "\r" and i + 1 < len(line) and line[i + 1] == "\n":
                i += 1
            i += 1
            continue

        buf.append(ch)
        if ch in _QUOTE_CHARS:
            in_quote = not in_quote
        elif not in_quote and ch in _SPLIT_BOUNDARY_CHARS:
            s = "".join(buf).strip()
            if s:
                parts.append(s)
            buf = []
        i += 1

    if buf:
        s = "".join(buf).strip()
        if s:
            parts.append(s)
    return parts


def split_to_clauses(text: str, filter_short: bool = False) -> List[str]:
    """
    文本切分，与前端 report/citationMatch.ts splitToClauses 对齐。

    切分符：。！？；;!? 以及 \\n、\\r\\n、\\r
    引号内的句末标点不参与切分，避免误切对话内容。
    - filter_short=False：报告正文用，保留所有子句
    - filter_short=True：文档内容用，过滤 normalize 后长度 < 6 的短句（与前端一致）
    """
    raw = (text or "").replace("\r\n", "\n").strip()
    if not raw:
        return []

    lines = raw.splitlines(keepends=True)
    clauses = []

    for line in lines:
        stripped = line.strip()
        if not stripped:
            clauses.append(line)
            continue
        if stripped.startswith("#"):
            clauses.append(line)
            continue

        parts = _split_line_quote_aware(line)
        for s in parts:
            t = s.strip()
            if not t:
                continue
            if filter_short:
                # 与前端 citationMatch: normalizeForNgram(c).length >= 6
                norm = _normalize_for_filter(t)
                if len(norm) >= 6:
                    clauses.append(t)
            else:
                clauses.append(t)

    return clauses

def chinese_to_arabic(chinese: str) -> Optional[float]:

    if not chinese:
        return None

    parts = chinese.split("点")

    if len(parts) > 2:
        return None

    integer_part = parts[0]
    decimal_part = parts[1] if len(parts)==2 else ""

    integer_val = parse_chinese_integer(integer_part)

    if integer_val is None:
        return None

    decimal_val = parse_chinese_decimal(decimal_part) if decimal_part else 0
    if decimal_val is None:
        logger.info(f"integer_val{integer_val}")
        logger.info(f"decimal_val{decimal_val}")
        # print(f"integer_val{integer_val}")
        # print(f"decimal_val{decimal_val}")
        return None
    return integer_val + decimal_val


def parse_chinese_integer(chinese: str):

    if not chinese:
        return 0

    result = 0
    temp = 0

    for i,ch in enumerate(chinese):

        num = CHINESE_NUMBERS.get(ch)

        if num is None:
            return None

        if ch == "十":
            if i == 0:
                temp = 10
            else:
                temp *= 10

        elif ch in ["百","千","万","亿"]:
            if temp == 0:
                temp = num//10
            else:
                temp *= num

            result += temp
            temp = 0

        else:
            if temp == 0:
                temp = num
            else:
                temp += num

    result += temp
    return result


def parse_chinese_decimal(chinese):

    result = 0
    denominator = 10

    for ch in chinese:

        num = CHINESE_NUMBERS.get(ch)

        if num is None or num > 9:
            return None

        result += num/denominator
        denominator *= 10

    return result


def parse_arabic_like_number(raw: str):

    normalized = raw.replace(",","")

    m = re.match(r'^(\d+(?:\.\d+)?)([十百千万亿])?$', normalized)

    if not m:
        return None

    base = float(m.group(1))

    unit = m.group(2)

    multiplier = ARABIC_UNIT_MULTIPLIER.get(unit,1)

    return base * multiplier


def extract_numbers(text:str):

    numbers = []

    occupied = set()

    arabic_regex = r'(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?(?:[十百千万亿])?'

    for m in re.finditer(arabic_regex,text):

        val = parse_arabic_like_number(m.group())

        if val is not None:

            numbers.append({
                "value":val,
                "original":m.group(),
                "start":m.start(),
                "end":m.end()
            })

            for i in range(m.start(),m.end()):
                occupied.add(i)

    chinese_regex = r'[零一二三四五六七八九十百千万亿点]+'

    for m in re.finditer(chinese_regex,text):

        s,e = m.start(),m.end()

        if any(i in occupied for i in range(s,e)):
            continue

        val = chinese_to_arabic(m.group())

        if val is not None:
            numbers.append({
                "value":val,
                "original":m.group(),
                "start":s,
                "end":e
            })

    return numbers


def is_date_related(text,number):

    value = number["value"]

    after = text[number["end"]:number["end"]+1]

    if after=="年" and 1900<=value<=2099:
        return True

    if after=="月" and 1<=value<=12:
        return True

    if after in ["日","号"] and 1<=value<=31:
        return True

    return False


def check_number_consistency(statement: str, reference: str) -> bool:
    """
    检查正文与文档句的关键数字是否一致。
    若正文有多个关键数字且与文档句矛盾或完全无交集，返回 False。
    用于在 LLM 验证前过滤明显错误的匹配。
    """
    stmt_nums = extract_numbers(statement)
    ref_nums = extract_numbers(reference)
    stmt_nums = [n for n in stmt_nums if len(n["original"]) >= 2 and not is_date_related(statement, n)]
    ref_nums = [n for n in ref_nums if len(n["original"]) >= 2 and not is_date_related(reference, n)]

    ref_vals = {n["value"] for n in ref_nums}

    if not stmt_nums:
        return True

    matched = sum(1 for n in stmt_nums if n["value"] in ref_vals)

    # 正文有 2+ 个关键数字，但无一与文档匹配 → 拒绝（如 586户+2000万 vs 1273户+4286人）
    if len(stmt_nums) >= 2 and matched == 0:
        logger.info(f"[cite_数字校验] 正文有{len(stmt_nums)}个关键数字，与文档句无交集，拒绝")
        return False

    # 正文有 1+ 个关键数字，文档也有数字，但无一匹配 → 拒绝（可能矛盾，如 586 vs 1273）
    if len(stmt_nums) >= 1 and ref_vals and matched == 0:
        logger.info(f"[cite_数字校验] 正文数字与文档句矛盾或无交集，拒绝")
        return False

    return True


def find_best_number_excerpt(source:str,query:str,max_span=3,max_len=280):

    query_nums = extract_numbers(query)

    valid_query = [n for n in query_nums if len(n["original"])>=2 and not is_date_related(query,n)]

    if not valid_query:
        return None

    clauses = split_to_clauses(source)

    clause_numbers = [
        [n for n in extract_numbers(c) if len(n["original"])>=2 and not is_date_related(c,n)]
        for c in clauses
    ]

    best = None
    best_count = 0

    for i in range(len(clauses)):

        for span in range(1,min(max_span,len(clauses)-i)+1):

            text = "".join(clauses[i:i+span])

            numbers = []

            seen = set()

            for j in range(i,i+span):

                for n in clause_numbers[j]:

                    if n["value"] not in seen:
                        numbers.append(n)
                        seen.add(n["value"])

            match = 0
            matched = []

            for q in valid_query:

                for n in numbers:

                    if q["value"] == n["value"]:
                        match+=1
                        matched.append(n["value"])
                        break

            if match == len(valid_query):

                return NumberBestMatch(
                    text=text[:max_len],
                    score=1.0,
                    clauseIndex=i,
                    span=span,
                    matchNumber=matched
                )

            if match > best_count:

                best_count = match

                best = NumberBestMatch(
                    text=text[:max_len],
                    score=match/len(valid_query),
                    clauseIndex=i,
                    span=span,
                    matchNumber=matched
                )

    return best



